#include <iostream>
#include <limits>
int main() {
    int value{};
    if (!(std::cin >> value)) {
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    }
    if (std::cin >> value) { std::cout << value << '\n'; }
    else { std::cout << "invalid\n"; }
}

