#include <iostream>
#include <sstream>
#include <string>
struct Stock { int value{5}; };
bool apply(Stock& stock, const std::string& kind, int amount) {
    if (amount < 0 || amount > 1000) { return false; }
    if (kind == "add" && amount <= 1000 - stock.value) { stock.value += amount; return true; }
    if (kind == "remove" && amount <= stock.value) { stock.value -= amount; return true; }
    return false;
}
int main() {
    Stock stock;
    std::string line;
    int lines{}, accepted{}, rejected{};
    while (std::getline(std::cin, line)) {
        if (++lines > 50 || line.size() > 200) { std::cout << "invalid\n"; return 0; }
        std::istringstream parser{line};
        std::string kind;
        int amount{};
        if (!(parser >> kind >> amount)) { ++rejected; continue; }
        parser >> std::ws;
        if (!parser.eof() || !apply(stock, kind, amount)) { ++rejected; continue; }
        ++accepted;
    }
    if (std::cin.bad()) { std::cout << "invalid\n"; return 0; }
    std::cout << accepted << ' ' << rejected << ' ' << stock.value << '\n';
}
